// Generated by scripts/build-legal-pages.cjs. Static text only; no patient information.
window.AlphastarLegalTranslations = Object.freeze({
  "legal.home": "Balik sa Simula",
  "legal.skip": "Pumunta sa nilalaman",
  "legal.contents": "Sa pahinang ito",
  "legal.updated": "Huling update:",
  "legal.updatedDate": "5 Nobyembre 2026",
  "legal.scope": "Ito rin ang mga notice na nasa mobile app. May hiwalay na paliwanag sa ibaba tungkol sa paggamit ng website. Magtanong sa clinic kung may hindi malinaw.",
  "legal.legalNavigation": "Mga notice at tuntunin",
  "legal.privacy": "Privacy ng Datos",
  "legal.terms": "Mga Tuntunin at Kondisyon",
  "legal.privacyPageTitle": "Privacy ng Datos | Alphastar",
  "legal.termsPageTitle": "Mga Tuntunin at Kondisyon | Alphastar",
  "legal.privacyDescription": "Basahin kung paano ginagamit ang impormasyon sa Alphastar Mobile at website, at kung paano magtanong tungkol sa privacy.",
  "legal.termsDescription": "Basahin ang mga tuntunin sa paggamit ng Alphastar Mobile, home-service requests, SMAPE and MAPE forms, at website.",
  "legal.privacy.introduction": "Ipinapaliwanag dito kung anong impormasyon ang ginagamit ng Alphastar Mobile, bakit ito kailangan, at paano ka makakapagtanong tungkol sa datos mo. Kasama rito ang patient account, home-service requests, SMAPE and MAPE forms, saved drafts, security settings, at support.",
  "legal.privacy.scope.title": "Para kanino ang notice na ito",
  "legal.privacy.scope.body": "Para ito sa mga pasyenteng gumagamit ng Alphastar Mobile kasama ang Alphastar Laboratory & Multi-Specialty Clinic. Para sa account mo at awtorisadong clinic staff ang personal at medical information mo, hindi para sa ibang pasyente. Hindi pinapalitan ng app notice na ito ang consent o impormasyong ibinibigay ng clinic para sa pangangalagang medikal.",
  "legal.privacy.information.title": "Impormasyong ginagamit ng app",
  "legal.privacy.information.body": "Depende ito sa mga feature na ginagamit mo:",
  "legal.privacy.information.bullet0": "Account details: pangalan, email, contact number, paraan ng pag-sign in, at account ID. Puwede ring may profile picture ang account.",
  "legal.privacy.information.bullet1": "Profile at home-service details: address, napiling serbisyo, gustong petsa at oras, notes, at appointment status o history.",
  "legal.privacy.information.bullet2": "Iba pang clinic-linked records para sa account mo, gaya ng queue status o payment records, kung mayroon.",
  "legal.privacy.information.bullet3": "SMAPE at MAPE information: patient details, school/guardian o company/emergency-contact details, medical history, examination answers, vital signs, petsa ng submission, at clinic review status o remarks.",
  "legal.privacy.information.bullet4": "Security details: sign-in sessions, protektadong records para sa pag-check ng PIN, email-verification steps, at status ng security requests.",
  "legal.privacy.information.bullet5": "Service notifications, form drafts na naka-save sa device, at impormasyong pinili mong ipadala sa clinic support.",
  "legal.privacy.purposes.title": "Bakit ginagamit ang impormasyon",
  "legal.privacy.purposes.body": "Ginagamit ito para matukoy ang patient account mo, ma-update ang details, maayos ang home-service requests, makita ang appointment at SMAPE or MAPE status, matulungan ang clinic sa review, maipadala ang service notices o verification emails, at maprotektahan ang account. Kailangan ng angkop na legal na batayan para sa health information, gaya ng partikular na consent o ibang batayang pinapayagan ng batas sa Pilipinas. Hindi awtomatikong pahintulot sa lahat ng paggamit ng datos ang pagbasa sa policy na ito.",
  "legal.privacy.access.title": "Sino ang puwedeng makakita",
  "legal.privacy.access.body": "Maaaring makita ng awtorisadong clinic staff at administrators ang impormasyong kailangan para sa kanilang trabaho. Ginagamit din ng technical providers ang datos na kailangan para gumana ang kaugnay na feature. Maaaring kailangang magbigay ng impormasyon dahil sa isang wastong legal na obligasyon. Magtanong sa clinic kung sino ang may access sa isang record o tungkol sa isang partikular na pagbibigay ng impormasyon.",
  "legal.privacy.providers.title": "Mga serbisyong tumutulong sa app",
  "legal.privacy.providers.body": "Gumagamit ang app ng Google/Firebase para sa authentication, patient data, uploaded files, at saved Staff Support conversations. Ang clinic backend sa Render ang humahawak sa suportadong account, appointment, medical-form, at staff-messaging operations. Email providers ang naghahatid ng verification messages. Sa PSGC Cloud kinukuha ang mga listahan ng lugar; kinukuha lang ng requests na iyon ang location lists, hindi ang buong home address mo. Maaaring iproseso ng mga provider ang connection details at datos na kailangan nila, kabilang ang pagproseso sa labas ng Pilipinas. May sarili ring privacy practices ang external website o email app na bubuksan mo.",
  "legal.link.Firebase privacy information": "Privacy ng Firebase",
  "legal.link.Render Privacy Policy": "Privacy Policy ng Render",
  "legal.privacy.drafts.title": "Saved forms at storage ng device",
  "legal.privacy.drafts.body": "Puwedeng i-save bilang draft sa device ang hindi pa tapos na SMAPE, MAPE, booking, reschedule, at profile forms. Hindi pa submitted record o confirmed appointment ang draft. Naka-encrypt ang persisted drafts sa suportadong Android devices. May pitong araw para sa draft recovery; hindi tinatanggap sa pagbasa ang expired drafts. Puwedeng hindi na marecover ang draft kapag nagka-storage problem, nag-clear ng app data, o nag-install ulit. May patient-data caches at navigation information din para makatulong sa pagbukas muli ng pages. Hindi lahat ng cached copy ay gumagamit ng draft encryption. Ingatan ang phone at mag-sign out sa shared device.",
  "legal.privacy.security.title": "Login, PIN, at email verification",
  "legal.privacy.security.body": "Puwedeng mag-sign in gamit ang email/password o Google. Google ang namamahala sa Google account password; para sa email/password accounts ang Change Password ng app. Protektadong verification records ang gamit sa account PIN, hindi nababasang PIN values. Karaniwang nagla-lock ang app pagkatapos ng sampung minutong walang activity at bumabalik sa Home kapag matagumpay ang PIN unlock. Kapag saglit lang lumipat ng app, dapat manatili ang kasalukuyang page. Nakakabawas ng panganib ang safeguards pero hindi nito magagarantiya ang seguridad ng device o online service sa lahat ng oras. Huwag ibigay ang PIN, password, o email code.",
  "legal.privacy.chat.title": "Help Bot at saved chat",
  "legal.privacy.chat.body": "Built-in, rule-based English/Tagalog guides ang gamit ng Help Bot, hindi generative AI service. Itinutugma nito ang tanong sa suportadong clinic topics at puwedeng gamitin ang available na account information mo para sa suportadong status features. Automated guidance ang mga sagot, hindi mensahe mula sa staff.",
  "legal.privacy.chat.bullet0": "Sa suportadong Android device, naka-encrypt na sine-save ang messages, timestamps, language choices, Help Bot feedback, at hindi pa tapos na chat drafts, na hiwalay para sa bawat patient account. Hindi awtomatikong ipinapadala sa clinic staff ang Help Bot feedback.",
  "legal.privacy.chat.bullet1": "Walang automatic expiry ang saved chat at nananatili ito pagkatapos ng logout para maipagpatuloy ng parehong pasyente sa susunod na login. Hindi nabubura ang usapan sa pagsara ng chat o kapag nagka-storage error. Maaaring hindi na marecover kapag ni-clear ang app data, nag-reinstall, o nawala ang device encryption key.",
  "legal.privacy.chat.bullet2": "Hindi bina-backup o sini-sync ng feature na ito ang Help Bot chat sa ibang device. Ipinapakita sa chat ang storage failure o unsupported web storage sa halip na mag-save ng plaintext transcript.",
  "legal.privacy.chat.bullet3": "Draft para sa review mo ang Prepare a Support Message; hindi pa ito ipinapadala. Puwedeng gumawa ang My Schedule ng message gamit ang loaded home-service details at booking reference.",
  "legal.privacy.staff-chat.title": "Staff Support conversations at feedback",
  "legal.privacy.staff-chat.body": "Sariling messaging service ng Alphastar ang Staff Support para makausap ang awtorisadong clinic staff, na hiwalay sa Help Bot. Kapag pinili ang Chat with staff, ibinabahagi sa awtorisadong clinic staff sa loob ng Alphastar ang account name, email, at patient ID mo. Hindi awtomatikong ibinabahagi ang booking reference o Help Bot transcript.",
  "legal.privacy.staff-chat.bullet0": "Sine-save sa clinic backend ang staff messages, sender information, timestamps, connection status, at anumang feedback na isinumite mo. Puwedeng tingnan ng awtorisadong staff at administrators ang conversations at feedback para sa support duties. Hindi nagiging anonymous sa clinic ang staff account kapag clinic display name ang gamit nito.",
  "legal.privacy.staff-chat.bullet1": "Maipagpapatuloy ang staff conversations pagkatapos mag-sign in sa parehong patient account. Nasa Earlier messages ang mas lumang mensahe. Hindi nabubura ang saved staff transcript sa logout, pagsara ng chat, pagtatapos ng usapan, o pag-alis ng notification. Napupunta sa staff chat history ang tinapos na usapan; puwedeng buksan muli ito ng susunod na mobile support request.",
  "legal.privacy.staff-chat.bullet2": "Opsyonal ang Like/Dislike rating at komento. Puwedeng tapusin ang usapan nang wala ang alinman. Nakikita ng awtorisadong clinic staff ang isinumite sa staff-chat feedback form; iba ito sa local Help Bot feedback.",
  "legal.privacy.staff-chat.bullet3": "Nau-update ang messages at pansamantalang typing indicators habang may koneksyon. Activity lang ang ipinapakita ng typing indicator, hindi garantiya na naipadala, nabasa, o nasagot ang mensahe. Hindi kinokopya ang staff conversations sa local Help Bot history. Huwag maglagay ng passwords, PINs, email codes, o hindi kailangang medical information sa chat.",
  "legal.privacy.records.title": "Medical forms, pag-print, at notifications",
  "legal.privacy.records.body": "Naka-store ang submitted SMAPE and MAPE forms para sa clinic review. Status lang ng form ang Pending, Approved, at iba pang review labels; hindi ito diagnosis o pangakong may clinical clearance. Kapag nag-print o nag-save gamit ang print tools ng phone, nasa labas na ng access controls ng app ang kopya. Panatilihin itong pribado. Kung may pahintulot sa device notifications, puwedeng ipadala ang home-service reminders at staff updates sa Expo at Google FCM o Apple APNs gamit ang device push token, account ID at notification content. Nakadepende ang delivery sa internet at provider configuration. Nananatili sa app ang notifications; hindi nabubura ang appointment o medical record kapag tinanggal ang notification. Ina-update ang device registration sa sign-in at session cleanup; hindi agad nare-revoke ng offline logout ang registration na nasa server.",
  "legal.privacy.retention.title": "Logout at mga hiling na mag-delete",
  "legal.privacy.retention.body": "Sinusubukan ng logout na alisin ang local drafts, cached patient data, at saved session ng kasalukuyang account. Hindi nito binubura ang clinic account, submitted SMAPE and MAPE forms, o appointment history sa mga sistema ng clinic. Maaaring iba-iba ang retention requirements ng clinic records, provider logs, at backups. Walang iisang takdang retention period para sa lahat ng server records na nakasaad sa app na ito. Itanong sa clinic ang retention ng mismong record at ang proseso ng deletion o account closure, pati ang impormasyong kailangang panatilihin.",
  "legal.privacy.choices.title": "Mga pagpipilian at karapatan sa privacy",
  "legal.privacy.choices.body": "Puwede mong tingnan ang profile at baguhin ang editable details sa app. Sa Data Privacy Act of 2012 ng Pilipinas, maaaring kabilang sa mga karapatan ang malaman kung paano ginagamit ang datos, access, pagwawasto, pagtutol o pagbawi ng consent, at pag-block o pag-delete kung pasok sa legal na kondisyon. Puwede ring magreklamo sa National Privacy Commission. May mga legal na tungkulin at exceptions na puwedeng makaapekto sa request. Ipapaliwanag ito ng clinic kung magtatanong ka; walang instant account-deletion button sa bersyong ito.",
  "legal.link.Read the Data Privacy Act of 2012": "Basahin ang Data Privacy Act of 2012",
  "legal.privacy.minors.title": "Mga pasyenteng kailangan ng guardian",
  "legal.privacy.minors.body": "Kung minor ang pasyente o kailangan ng awtorisadong representative, magtanong sa clinic tungkol sa account at kinakailangang consent. Impormasyong may pahintulot kang ibigay lang ang gamitin. Hindi awtomatikong kapalit ng consent process ng clinic ang paglagay ng guardian details sa SMAPE form.",
  "legal.privacy.contact.title": "Mga tanong o concern sa privacy",
  "legal.privacy.contact.body": "Gamitin ang Profile > Staff Support sa app o mag-email sa info@alphastarlabclinic.com at hilinging makausap ang taong responsable sa patient privacy. Sabihin kung kailangan mo ng access, pagwawasto, account closure, o tulong sa privacy concern. Maaaring kailangang i-check ng clinic ang identity mo. Huwag isama ang password, PIN, verification code, o buong medical record sa unang message.",
  "legal.link.Email Alphastar Clinic": "Mag-email sa Alphastar Clinic",
  "legal.privacy.updates.title": "Mga update sa notice",
  "legal.privacy.updates.body": "Tingnan ang petsa ng huling update kapag binabasa ang notice. Dapat itong baguhin kapag nagbago ang app features o paraan ng paghawak ng clinic sa datos. Hindi inaalis ng bagong privacy notice ang mga karapatan mo o pinapalitan ang consent na kailangan ng batas para sa bagong layunin. Magtanong sa clinic kung kailangan ng paliwanag tungkol sa pagbabago.",
  "legal.privacy.website-chat.title": "Ang website at Help Bot nito",
  "legal.privacy.website-chat.body": "Nagbibigay ng impormasyon tungkol sa clinic at mobile app ang public website. Built-in, rule-based English/Tagalog replies ang gamit ng Help Bot, hindi generative AI service. Hindi ka nito sina-sign in, tinitingnan ang patient account o SMAPE at MAPE records, o nagsu-submit ng booking. Nasa memory ng kasalukuyang page ang Help Bot messages, support drafts, timestamps, at bot feedback at nawawala sa reload. Hindi awtomatikong ibinabahagi sa clinic staff ang Help Bot transcript. Hindi pa naipapadala ang message kapag gumawa ng email draft o nag-copy.",
  "legal.privacy.website-staff-chat.title": "Website Staff Support at guest sessions",
  "legal.privacy.website-staff-chat.body": "Sa Alphastar messaging ka ikinokonekta ng Staff Support sa awtorisadong clinic staff. Ilagay ang pangalan at email at pumayag na ibahagi ang mga ito sa clinic at i-save ang usapan bago buksan ang staff chat. Hiwalay na guest identity ito, hindi access sa mobile patient account.",
  "legal.privacy.website-staff-chat.bullet0": "Sine-save sa Firebase/Render backend ng Alphastar ang staff messages, sender details, timestamps, connection status, at anumang feedback na isinumite mo. Puwedeng tingnan ng awtorisadong clinic staff at administrators ang mga ito para sa support duties.",
  "legal.privacy.website-staff-chat.bullet1": "May pribadong pansamantalang token sa kasalukuyang page para pahintulutan ang access sa guest conversation. Hindi ito patient login. Huwag ibahagi ang token o gumamit ng shared browser para sa pribadong support details.",
  "legal.privacy.website-staff-chat.bullet2": "Puwedeng i-minimize ang chat o bumalik sa Help Bot at magpatuloy sa parehong loaded page. Humihiling na tapusin ang guest conversation kapag ni-refresh o iniwan ang page. Puwede ring matapos ito dahil sa disconnection o inactivity; hindi garantisado ang pagdating ng exit request. Hindi sapat ang pangalan o email para mabawi ang nakaraang guest conversation.",
  "legal.privacy.website-staff-chat.bullet3": "Hindi nabubura ang saved clinic transcript sa pagtatapos ng guest conversation, pagsara ng page, o pag-clear ng browser data. Walang account-linked recovery sa website guest sessions gaya ng nasa mobile app.",
  "legal.privacy.website-staff-chat.bullet4": "Opsyonal ang Like/Dislike rating at komento; puwedeng magtapos nang wala ang alinman. Nakikita ng awtorisadong clinic staff ang isinumiteng staff-chat feedback. Activity lang ang ipinapakita ng pansamantalang typing indicator, hindi naipadalang mensahe o garantisadong sagot. Huwag maglagay ng passwords, PINs, verification codes, o hindi kailangang medical details.",
  "legal.privacy.website-storage.title": "Wika at browser storage ng website",
  "legal.privacy.website-storage.body": "Sine-save ng website ang English/Tagalog choice sa local storage ng browser para maalala ito sa susunod na pagbisita. Hiwalay ang wika ng Help Bot sa wika ng website. Puwede ring i-cache ng browser ang page files. Puwedeng ma-reset ang language choice kapag nag-clear ng browser data ng website. Hindi nito binubura ang mobile-app account, clinic records, o messages na ipinadala sa ibang serbisyo.",
  "legal.privacy.website-providers.title": "Website hosting, mapa, at external links",
  "legal.privacy.website-providers.body": "Kumokonekta ang browser sa website hosting at, kapag na-load, sa Google Fonts at naka-embed na Google Map. Maaaring iproseso ng mga serbisyong ito ang IP address, browser information, at request details. Kapag nagbukas ng Messenger, email, directions, o app-download link, kokonekta ka sa kaugnay na external service. May sarili silang privacy practices. Walang nakasaad na iisang retention period para sa provider logs sa website; sa clinic magtanong tungkol sa partikular na concern.",
  "legal.link.Google Privacy Policy": "Privacy Policy ng Google",
  "legal.terms.introduction": "Ipinapaliwanag dito ang responsableng paggamit ng Alphastar Mobile at kung ano ang aasahan sa patient features. Basahin ito kasama ng Privacy Policy. Magtanong sa clinic kung may hindi malinaw bago magsumite ng impormasyon o humiling ng serbisyo.",
  "legal.terms.purpose.title": "Para saan ang Alphastar Mobile",
  "legal.terms.purpose.body": "Tumutulong ang Alphastar Mobile sa pag-manage ng profile, pag-request ng available na home service, pag-check ng appointment updates, pag-submit at pagtingin ng SMAPE and MAPE forms, pag-manage ng account security, at pagkuha ng gabay tungkol sa clinic o app. Hindi sa app bina-book ang in-person clinic consultations o walk-in visits. Puwedeng magbago ang available na serbisyo at features; kumpirmahin sa staff kung kailangan.",
  "legal.terms.account.title": "Account at tamang impormasyon",
  "legal.terms.account.body": "Gamitin ang sarili mong patient account, o kumilos lang kung may wastong awtoridad para sa pasyente. Ibigay ang tamang contact details at kumpletong home-service address. Panatilihing updated ang details para makontak ka ng clinic. Sundin ang requirements ng clinic kung kailangan ng guardian o representative. Huwag magpanggap na ibang tao o gumamit ng account o medical information ng iba nang walang pahintulot.",
  "legal.terms.credentials.title": "Ingatan ang login at PIN",
  "legal.terms.credentials.body": "Panatilihing pribado ang password, anim-na-digit na PIN, at email verification codes. Gamitin ang Security Settings para sa suportadong pagbabago. May password-change verification flow ang email/password accounts; sa Google pinapalitan ang Google password. Mag-sign out sa shared phone at ipaalam sa clinic kung may pinaghihinalaang unauthorized access. Huwag mag-send ng login credentials sa Chat With Us o Staff Support.",
  "legal.terms.requests.title": "Kailangang kumpirmahin ang home service",
  "legal.terms.requests.body": "Hindi pa confirmed appointment ang submitted request. Kailangang kumpirmahin ng staff ang serbisyo, lugar, available na schedule, at fees. Hindi lahat ng serbisyo sa clinic ay puwede sa bahay. Kumpletuhin ang requirements sa Book Appointment, i-check ang address, at tingnan ang request bago mag-submit. Hindi kumpirmasyon ang loading screen, draft, o lumang cached status.",
  "legal.terms.changes.title": "Reschedule, cancellation, at fees",
  "legal.terms.changes.body": "Gamitin ang Appointment Schedule para sa available na reschedule o cancellation. Basahin ang form, kumpirmahin bago mag-submit, at tingnan ang bagong status. Maaaring kailanganin ang clinic confirmation sa reschedule request. Magtanong sa staff kung hindi available ang option. Kumpirmahin sa clinic ang presyo, home-service charges, payment arrangements, at refund o cancellation conditions. Walang ipinapasok na automatic charge, penalty, o pangakong refund ang mga tuntuning ito.",
  "legal.terms.smpe.title": "SMAPE at MAPE forms at medical information",
  "legal.terms.smpe.body": "Sagutan nang tapat ang angkop na Student Medical & Physical Examination (SMAPE) o Medical & Physical Examination (MAPE) form at tingnan ang mga sagot bago mag-submit. May school at guardian details ang SMAPE; may company/occupation at emergency-contact details ang MAPE. Sa Medical History makikita ang submissions at review status. Mag-edit lang kung pinapayagan ng app, o humingi ng tulong sa staff para sa correction. Hindi kapalit ng examination, diagnosis, medical certificate, o treatment advice ng clinician ang submitted form o approved review label. Ingatan ang printed o saved copy.",
  "legal.terms.drafts.title": "Drafts, mobile data, at availability",
  "legal.terms.drafts.body": "Sa device lang nananatili ang unfinished work kapag naka-save bilang draft; hindi pa ito clinic request. Puwedeng hindi marecover matapos ang recovery window, storage problems, pag-clear ng app data, o reinstall. Tingnan ang mga sagot kapag binuksan ulit ang form. Kailangan ng gumaganang mobile data o Wi-Fi para sa sign-in, live status, submissions, account-security changes, at Staff Support. Puwedeng hindi updated ang cached pages. Tingnan muna ang confirmation o status bago ulitin ang submission.",
  "legal.terms.support.title": "Help Bot at clinic support",
  "legal.terms.support.body": "Rule-based automated guide ang Help Bot, hindi clinician o live staff. Hindi kinukumpirma ng mga sagot nito ang booking, dini-diagnose ang kondisyon, o ginagarantiya ang sagot ng staff. Hiwalay na messaging service ng Alphastar ang Staff Support kasama ang awtorisadong clinic personnel. Sine-save ang messages para sa support at follow-up; hindi nabubura ang transcript sa pagtatapos ng usapan. Opsyonal ang Like/Dislike rating at komento, at hindi kailangang magbigay ng alinman para tapusin ang usapan. Nakadepende sa koneksyon ang staff availability at delivery; hindi pangako ng agarang sagot ang typing indicator. Kung urgent ang medical concern, kumontak ng emergency services o pumunta sa angkop na medical facility; huwag hintayin ang chat.",
  "legal.terms.conduct.title": "Gamitin nang may respeto ang app",
  "legal.terms.conduct.body": "Gamitin ang app para lang sa legal at awtorisadong patient at clinic purposes. Huwag:",
  "legal.terms.conduct.bullet0": "Mang-harass, manakot, mang-abuso, o magpanggap na pasyente o staff.",
  "legal.terms.conduct.bullet1": "Magsumite ng maling forms, requests na alam mong mapanlinlang, spam, o paulit-ulit na requests para guluhin ang clinic.",
  "legal.terms.conduct.bullet2": "Subukang pumasok sa account ng iba, kumuha ng impormasyon ng ibang pasyente, lampasan ang access controls, o magbahagi ng confidential records nang walang awtoridad.",
  "legal.terms.conduct.bullet3": "Mag-upload ng harmful files, samantalahin ang app, o guluhin ang mga serbisyo o network nito.",
  "legal.terms.privacy.title": "Privacy at external services",
  "legal.terms.privacy.body": "Basahin ang Privacy Policy tungkol sa account information, health forms, saved drafts, service providers, at Staff Support conversations. Magbigay lang ng impormasyong may awtoridad kang ibahagi. Sakop ng mga notice na ito ang built-in staff messaging ng Alphastar. May sariling terms at privacy practices ang external websites, email, at ibang contact links. Huwag magsumite ng hindi kailangang sensitive information sa mga channel na iyon. Hindi blanket permission sa ibang paggamit ng health information ang pagbasa sa mga tuntuning ito.",
  "legal.terms.content.title": "App content at mga limitasyon",
  "legal.terms.content.body": "Igalang ang mga karapatan sa pangalan, logo, software, at clinic materials ng Alphastar. Hindi ka hinahadlangan ng mga tuntuning ito na humingi o magtago ng awtorisadong kopya ng sarili mong impormasyon. Maaaring magkaroon ng outages, delays, o errors; kontakin ang staff kung may maling request o record. Walang inaalis na karapatan o responsibilidad na hindi puwedeng alisin ayon sa batas. Hindi waiver ng clinical responsibilities o patient privacy rights ang app terms na ito.",
  "legal.terms.contact.title": "Mga tanong, concern, at update",
  "legal.terms.contact.body": "Kausapin ang staff sa Profile > Staff Support sa app o sa info@alphastarlabclinic.com kung kailangan ng paliwanag, tulong sa request, o correction. Tingnan ang petsa ng huling update para sa mga pagbabago. Hindi tahimik na nagdadagdag ng charges ang bagong notice o pinapalitan ang consent na kailangan ng batas. Gumamit ng updated na app at basahin ang notices kapag may pagbabago sa features.",
  "legal.terms.website-use.title": "Paggamit ng website",
  "legal.terms.website-use.body": "May public clinic information, automated guide, Staff Support, contact links, at app-download information ang website. Hindi ito patient-account portal, booking confirmation, medical consultation, o emergency service. Sa Alphastar Android app gamitin ang available na home-service at patient-form features. Sa official link lang ng clinic mag-download kapag available ito. Magtanong sa staff kung kailangang kumpirmahin ang download link o clinic detail. Huwag magpanggap na ibang tao, abusuhin ang chat, o subukang pumasok nang walang awtoridad.",
  "legal.terms.website-guidance.title": "Website information at pagpili ng wika",
  "legal.terms.website-guidance.body": "Puwedeng magbago ang clinic information. Kumpirmahin sa staff ang serbisyo, paghahanda, fees, at schedule bago umasa rito. Parehong notice ang ipinapaliwanag sa English at Tagalog; magtanong kung hindi malinaw ang wording. Hindi kumpirmasyon ng request o pagpapadala sa staff ang replies at feedback buttons ng bot. Hiwalay ang pagbukas ng email draft o Messenger sa pagpapadala ng message. Hindi nire-record ang acceptance sa pagbasa ng pages, at hindi ito blanket consent sa paggamit ng health information.",
  "legal.terms.website-support.title": "Paggamit ng Staff Support bilang guest",
  "legal.terms.website-support.body": "Magbigay ng tamang contact information at gamitin nang may respeto ang Staff Support. Napupunta sa clinic ang mga mensaheng ipinadala sa staff chat, hindi tulad ng local Help Bot replies o prepared drafts. Maaaring iba-iba ang staff availability at maantala ang sagot. Puwedeng magtapos nang walang rating o komento. Hindi nabubura ang clinic transcript sa pagtatapos o pag-alis. Pansamantala ang website guest access at hindi ito maibabalik gamit lang ang pangalan o email matapos mag-refresh o umalis sa page. Registered patient account ang gamit ng mobile app para sa saved staff conversations. Hindi emergency service o kapalit ng medical care ang alinmang chat."
});
